// catalog.json: every question set and question (generated by tools/build-catalog.js,
// or live from the local server).
import { state } from './store.js';

export async function fetchCatalog() {
  const res = await fetch(`catalog.json?t=${Date.now()}`);
  if (!res.ok) throw new Error(`Could not load the question catalog (HTTP ${res.status})`);
  return res.json();
}

export const getSet = (setId) => state.catalog.sets.find((s) => s.id === setId);
export const getQuestion = (setId, n) => state.catalog.questions[setId]?.[n];
export const getSupport = (set) => state.catalog.support[set.language || 'cpp'];

export function allQuestions(set) {
  return set.categories.flatMap((c) => c.questions.map((n) => ({ ...getQuestion(set.id, n), category: c })));
}
